def load(p):
    t = open(TXT + p, encoding='utf-8').read()
    t = html.unescape(t)
    return re.sub(r'\s+', ' ', t)

TEXTS = {'tcells': load('PMC6399228.txt'), 'ostrich': load('PMC7694958.txt'),
         'coral': load('PMC13749476.txt'), 'wheat': load('PMC8850252.txt'),
         'endo': load('PMC4659675.txt'), 'stallion': load('PMC12785071.txt')}

FAILS = []
def W(key, doi, locator, access, quote):
    qn = re.sub(r'\s+', ' ', html.unescape(quote))
    ok = qn in TEXTS[key]
    if not ok:
        FAILS.append((key, quote[:80]))
    return {'doi': doi, 'locator': locator, 'access': access, 'quote': quote}

